#include <bits/stdc++.h>
using namespace std;using ll=long long;
struct Dinic{struct E{int v,next,cap;};int n;vector<int>head,dist,cur,q;vector<E>e;Dinic(int n_):n(n_),head(n,-1),dist(n),cur(n),q(n){}void add(int u,int v,int cap){e.push_back({v,head[u],cap});head[u]=e.size()-1;e.push_back({u,head[v],0});head[v]=e.size()-1;}bool bfs(){fill(dist.begin(),dist.end(),-1);int a=0,b=0;q[b++]=0;dist[0]=0;while(a<b){int u=q[a++];for(int i=head[u];i!=-1;i=e[i].next)if(e[i].cap&&dist[e[i].v]<0){int v=e[i].v;dist[v]=dist[u]+1;q[b++]=v;}}return dist[1]>=0;}int dfs(int u,int f){if(u==1)return f;for(int &i=cur[u];i!=-1;i=e[i].next){int v=e[i].v;if(e[i].cap&&dist[v]==dist[u]+1){int g=dfs(v,min(f,e[i].cap));if(g){e[i].cap-=g;e[i^1].cap+=g;return g;}}}return 0;}int flow(){int f=0;while(bfs()){cur=head;while(int g=dfs(0,INT_MAX))f+=g;}return f;}};
int main(){vector<int>rs={64,317,1027,2048,4096};int N=rs.back()*rs.back()-1;vector<int>lp(N+1),pr,M(N+1),mx(N+1);vector<int8_t>mu(N+1);mu[1]=1;mx[1]=1;for(int n=2;n<=N;n++){if(!lp[n]){lp[n]=n;pr.push_back(n);mu[n]=-1;}mx[n]=max(lp[n],mx[n/lp[n]]);for(int p:pr){if(p>lp[n]||1LL*n*p>N)break;lp[n*p]=p;mu[n*p]=p==lp[n]?0:-mu[n];}}for(int n=1;n<=N;n++)M[n]=M[n-1]+mu[n];cout<<"R,tail_U,tail_L,label_types,sign_types,pairs,unmatched_U,unmatched_L,Q,cut_labels,cut_deficiency,tail_excess,high_star_U,high_star_L\n";for(int R:rs){int X=R*R-1,U=0,L=0,hu=0,hl=0;unordered_map<int,array<int,2>> ct;for(int n=R;n<=X;n++)if(mu[n]){int ca=1,b=n;while(ca<R){int p=lp[b];ca*=p;b/=p;}int cb=1,a=n;while(cb<R){int p=mx[a];cb*=p;a/=p;}assert(a<R&&b<R&&gcd(a,b)==1&&n%(a*b)==0&&mu[n]==mu[a]*mu[b]*mu[n/(a*b)]);int s=mu[n]<0?0:1;if(s==0)U++;else L++;if(mx[n]>=R){assert(b==1);if(s==0)hu++;else hl++;}if(a>b)swap(a,b);ct[a*R+b][s]++;}int types=0;for(auto &p:ct)types+=(p.second[0]>0)+(p.second[1]>0);Dinic g(R+2+types);int k=R+2,INF=U+L+1;for(auto &p:ct){int a=p.first/R,b=p.first%R;for(int s=0;s<2;s++)if(p.second[s]){int v=k++;if(s==0){g.add(0,v,p.second[s]);g.add(v,a+2,INF);if(a!=b)g.add(v,b+2,INF);}else{g.add(v,1,p.second[s]);g.add(a+2,v,INF);if(a!=b)g.add(b+2,v,INF);}}}assert(k==g.n);int f=g.flow(),cl=0,def=0;for(int a=1;a<R;a++)cl+=(g.dist[a+2]>=0);for(auto &p:ct){bool a=g.dist[p.first/R+2]>=0,b=g.dist[p.first%R+2]>=0;def+=(a&&b?p.second[0]:0)-(a||b?p.second[1]:0);}assert(def==U-f);int hist=M[R-1],u=U-f+max(hist,0),l=L-f+max(-hist,0);assert(u-l==2LL*M[R-1]-M[X]);cout<<R<<','<<U<<','<<L<<','<<ct.size()<<','<<types<<','<<f<<','<<u<<','<<l<<','<<u-l<<','<<cl<<','<<def<<','<<U-L<<','<<hu<<','<<hl<<endl;}}
